import json, sys
sys.path.insert(0, "/workspace/src")
from blinker import Namespace, signal
case = json.load(sys.stdin)
class Name(str): pass
class Poison:
    def __hash__(self): raise RuntimeError("lookup happened before validation")
if case["mode"] == "invalid":
    name = {"integer": 7, "bytes": b"event", "none": None, "list": [], "poison": Poison()}[case["form"]]
